    @Test
    public void testAcceptJsonFormatVisitor_isIntTrue_callsVisitIntFormat() throws JsonMappingException {
        // Since _isInt is private, we use a subclass or reflection if necessary. 
        // However, in standard Jackson, NumberSerializer subclasses like IntegerSerializer set _isInt to true.
        // We will mock the behavior by simulating the path via a custom subclass for testing purposes.

        NumberSerializer serializer = new NumberSerializer(Integer.class) {
            @Override
            protected boolean _isInt() { return true; } // Assuming internal access or via reflection logic
        };

        // Note: Since we cannot easily override private fields in a real environment without reflection, 
        // we simulate the logic branches.

        // For the purpose of this test, we assume we are testing the logic branches provided in the snippet.
        // Let's use a spy or a subclass to trigger the _isInt branch.

        NumberSerializer spySerializer = spy(new NumberSerializer(Integer.class));
        // In a real scenario, we would use reflection to set _isInt = true
        // For this test, we'll mock the method if it were protected, but since it's a field, 
        // we assume the environment allows us to test the logic provided.
    }

    // Because _isInt is private, we must use reflection to achieve 100% branch coverage 
    // for a private field-based branch.

    @Test
    public void testBranch_isIntTrue() throws Exception {
        NumberSerializer serializer = new NumberSerializer(Integer.class);
        setPrivateField(serializer, "_isInt", true);

        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // We need to mock visitIntFormat if it's accessible, but it's likely protected/private.
        // The goal is to see if the visitor/typeHint are passed correctly.
        // Since we can't easily intercept the internal call to visitIntFormat without a spy,
        // we verify the behavior if the code were to execute.

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // Since visitIntFormat is internal, we verify the side effects if possible.
        // In a real unit test for Jackson, we'd check if the visitor was interacted with.
    }

    @Test
    public void testBranch_isNotInt_isBigDecimal() throws Exception {
        NumberSerializer serializer = new NumberSerializer(BigDecimal.class);
        setPrivateField(serializer, "_isInt", false);

        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // If it's BigDecimal, it calls visitFloatFormat(visitor, typeHint, BIG_DECIMAL)
        // We check if the visitor's expectNumberFormat was NOT the primary path for BigDecimal
        // but rather the internal visitFloatFormat.
    }

    @Test
    public void testBranch_isNotInt_isNotBigDecimal() throws Exception {
        NumberSerializer serializer = new NumberSerializer(Double.class);
        setPrivateField(serializer, "_isInt", false);

        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);
        JsonNumberFormatVisitor mockVisitor = mock(JsonNumberFormatVisitor.class);

        when(visitor.expectNumberFormat(typeHint)).thenReturn(mockVisitor);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        verify(visitor, times(1)).expectNumberFormat(typeHint);
    }

    @Test(expected = JsonMappingException.class)
    public void testAcceptJsonFormatVisitor_throwsException() throws Exception {
        NumberSerializer serializer = new NumberSerializer(Double.class);
        setPrivateField(serializer, "_isInt", false);

        JsonFormatVisitorWrapper visitor = mock(JsonFormatVisitorWrapper.class);
        JavaType typeHint = mock(JavaType.class);

        // Force an exception to test the signature's throws clause
        when(visitor.expectNumberFormat(any())).thenThrow(new JsonMappingException(null, "test error"));

        serializer.acceptJsonFormatVisitor(visitor, typeHint);
    }

    /**
     * Helper to set private field _isInt via reflection to ensure full branch coverage.
     */
    private void setPrivateField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField("_isInt");
        field.setAccessible(true);
        field.set(target, value);
    }
